def iter_concepts():
    for domain, classes in FIELDS.items():
        for pos, text in classes.items():
            for raw in text.replace('\n',' ').split('|'):
                item = ' '.join(raw.split()).strip()
                if item:
                    yield domain,pos,item

if __name__ == '__main__':
    all_terms=list(iter_concepts())
    print('Total concept specifications:',len(all_terms))
    print('Duplicate specs:',[x for x,v in Counter((p,t.lower()) for d,p,t in all_terms).items() if v>1][:30])
    for d,v in Counter(d for d,p,t in all_terms).items():print(d, v)
